#include "rt.h"
static char *arena;
#define SZ 0x420
void _start(void){
  arena = (char*)sbrk(0x4000);
  char *a = arena, *b = arena + SZ;
  u64 *fh = (u64*)(a + 0x10);            /* fake chunk header inside a's data */
  fh[0] = 0;                             /* fake prev_size */
  fh[1] = 0x410 | 1;                     /* fake size = 0x411 */
  u64 fake_user = (u64)(fh + 2);         /* fake user data */
  *(u64*)(fake_user + 0) = fake_user;    /* fake->fd = fake  (self ref) */
  *(u64*)(fake_user + 8) = fake_user;    /* fake->bk = fake  (self ref) */
  u64 *bh = (u64*)b;
  bh[0] = 0x410;                         /* b->prev_size = distance to fake */
  bh[1] &= ~1UL;                         /* clear prev_inuse (off-by-null) */
  put("a="); putx((u64)a); put(" b="); putx((u64)b); putnl();
  put("fake.size="); putx(fh[1]); putnl();
  put("b.prev_size="); putx(bh[0]); putnl();
  put("b.prev_inuse="); putd(bh[1]&1); putnl();
  put("free(b) -> backward consolidation -> unlink(fake) -> merge\n");
  put("malloc(0x800) -> "); putx(fake_user); put(" (inside a)\n");
  exit0();
}
